&lt;/ul&gt;
&lt;p&gt;&lt;img src=&#34;https://cimg1.17lai.site/data/2022/10/02/20221002200706-21.webp&#34; alt=&#34;Gitlab Mirror&#34;&gt;&lt;/p&gt;
&lt;h2 id=&#34;Github-仓库备份&#34;&gt;Github 仓库备份&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;最优秀的资源，大多只在短时间内出现！&lt;/p&gt;
&lt;p&gt;平时多备份你重要的仓库，以及你使用的仓库的重要上下游仓库！&lt;/p&gt;
&lt;/blockquote&gt;
&lt;blockquote&gt;
&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/appotry/docker-github-backup&#34;&gt;github-backup Githb&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;https://hub.docker.com/r/lnxd/github-backup&#34;&gt;github-backup Dockerhub&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/blockquote&gt;
&lt;figure&gt;&lt;div class=&#34;code-area&#34;&gt;&lt;pre class=&#34;line-numbers language-yaml&#34; data-language=&#34;yaml&#34; data-start=&#34;1&#34;&gt;&lt;code class=&#34;language-yaml&#34;&gt;githubback:
  image: lnxd&amp;#x2F;github-backup
  container_name: &amp;quot;githubback&amp;quot;
  hostname: githubback
  # ports:
    # - &amp;quot;80:80&amp;quot;
  volumes:
    - &amp;quot;$&amp;#123;USERDIR&amp;#125;&amp;#x2F;githubback&amp;#x2F;data:&amp;#x2F;home&amp;#x2F;docker&amp;#x2F;backups:rw&amp;quot;
  env_file:
    - .env
  environment:
    - HTTP_PROXY&amp;#x3D;http:&amp;#x2F;&amp;#x2F;[ip]:[port]
    - HTTPS_PROXY&amp;#x3D;http:&amp;#x2F;&amp;#x2F;[ip]:[port]
  restart: always&lt;/code&gt;&lt;/pre&gt;&lt;/div&gt;&lt;/figure&gt;
